    sprintf(textplace, "#chi^{2}/ndf = %.2f / %i",chi2_result.chi2_ , chi2_result.num_bins_ );
    //text->DrawLatex(0.10, 0.76, textplace);
    sprintf(textplace, "p-value = %.0f%%",100*chi2_result.p_value_ );
   // text->DrawLatex(0.10, 0.70, textplace);
    
    sprintf(textplace, ":   #chi^{2}/ndf: %.2f / %i ",chi2_result.chi2_ , chi2_result.num_bins_ );
