    //total_frac_err_hist->LabelsOption("h");
    //total_frac_err_hist->Draw( "SAME TEXT" );

     DrawBinContentsWithOptions(total_frac_err_hist);


    lg2->AddEntry( total_frac_err_hist, "total", "l" );

   //  std::cout<<"starting error leg names"<<std::endl;
    //////////////////////////////////  
